<?php
class BusinessController {
 private function guard():void{Auth::require();}
 public function products():void{$this->guard();$rows=db_all('SELECT * FROM products WHERE company_id=? ORDER BY id DESC',[company_id()]);View::render('business/products',compact('rows'));}
 public function productForm():void{$this->guard();View::render('business/product_form');}
 public function saveProduct():void{$this->guard();verify_csrf();$id=(int)($_POST['id']??0);$d=[company_id(),(trim($_POST['sku']??'')?:null),trim($_POST['name']??''),trim($_POST['category']??''),(float)($_POST['buy_price']??0),(float)($_POST['sell_price']??0),(int)($_POST['stock']??0),(int)($_POST['alert_stock']??5)];if($d[4]<0||$d[5]<0||$d[6]<0||$d[7]<0){flash('error','Les prix et quantités doivent être positifs.');redirect('/products/create');}if(!$d[2]){flash('error','Le nom du produit est obligatoire.');redirect('/products/create');}if($id){$d[]=$id;$d[]=company_id();Database::p()->prepare('UPDATE products SET sku=?,name=?,category=?,buy_price=?,sell_price=?,stock=?,alert_stock=? WHERE id=? AND company_id=?')->execute(array_slice($d,1));}else{$newId=db_exec('INSERT INTO products(company_id,sku,name,category,buy_price,sell_price,stock,alert_stock,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())',$d);if($d[6]>0){db_exec('INSERT INTO stock_movements(company_id,product_id,user_id,type,quantity,reason,created_at) VALUES(?,?,?,"in",?,"Stock initial",NOW())',[company_id(),$newId,Auth::user()['id'],$d[6]]);}}flash('success','Produit enregistré.');redirect('/products');}
 public function deleteProduct():void{$this->guard();verify_csrf();Database::p()->prepare('DELETE FROM products WHERE id=? AND company_id=?')->execute([(int)$_POST['id'],company_id()]);redirect('/products');}
 public function exportProducts():void{$this->guard();$rows=db_all('SELECT sku,name,category,buy_price,sell_price,stock,alert_stock FROM products WHERE company_id=?',[company_id()]);header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename=produits-fasobusiness.csv');$o=fopen('php://output','w');fputcsv($o,['sku','name','category','buy_price','sell_price','stock','alert_stock'],';');foreach($rows as $r)fputcsv($o,$r,';');exit;}
 public function importProducts():void{$this->guard();verify_csrf();if(empty($_FILES['csv']['tmp_name'])){flash('error','Fichier CSV requis.');redirect('/products');}$f=fopen($_FILES['csv']['tmp_name'],'r');$first=fgetcsv($f,0,';');if(!$first){flash('error','CSV vide.');redirect('/products');}$header=array_map('strtolower',$first);$count=0;while(($r=fgetcsv($f,0,';'))!==false){$a=array_combine($header,array_pad($r,count($header),''));if(empty($a['name']))continue;db_exec('INSERT INTO products(company_id,sku,name,category,buy_price,sell_price,stock,alert_stock,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())',[company_id(),$a['sku']??'', $a['name'],$a['category']??'',(float)($a['buy_price']??0),(float)($a['sell_price']??0),(int)($a['stock']??0),(int)($a['alert_stock']??5)]);$count++;}fclose($f);flash('success',"$count produit(s) importé(s).");redirect('/products');}
 public function stock():void{$this->guard();$products=db_all('SELECT id,name,stock FROM products WHERE company_id=? ORDER BY name',[company_id()]);$rows=db_all('SELECT m.*,p.name product,u.name user_name FROM stock_movements m JOIN products p ON p.id=m.product_id LEFT JOIN users u ON u.id=m.user_id WHERE m.company_id=? ORDER BY m.id DESC LIMIT 100',[company_id()]);View::render('business/stock',compact('products','rows'));}
 public function adjustStock():void{$this->guard();verify_csrf();$pid=(int)($_POST['product_id']??0);$delta=(int)($_POST['delta']??0);$reason=trim($_POST['reason']??'');if(!$pid||$delta===0||abs($delta)>100000||!$reason){flash('error','Produit, quantité non nulle et motif requis.');redirect('/stock');}$pdo=Database::p();$pdo->beginTransaction();try{$product=db_one('SELECT id,stock FROM products WHERE id=? AND company_id=? FOR UPDATE',[$pid,company_id()]);if(!$product)throw new RuntimeException('Produit introuvable.');$next=(int)$product['stock']+$delta;if($next<0)throw new RuntimeException('Le stock ne peut pas devenir négatif.');$pdo->prepare('UPDATE products SET stock=? WHERE id=? AND company_id=?')->execute([$next,$pid,company_id()]);db_exec('INSERT INTO stock_movements(company_id,product_id,user_id,type,quantity,reason,created_at) VALUES(?,?,?,"adjustment",?,?,NOW())',[company_id(),$pid,Auth::user()['id'],abs($delta),$reason]);$pdo->commit();Security::audit('stock.adjusted','product',$pid,['delta'=>$delta,'reason'=>$reason]);flash('success','Stock mis à jour.');}catch(Throwable $e){$pdo->rollBack();flash('error',$e->getMessage());}redirect('/stock');}
 public function customers():void{$this->guard();$rows=db_all('SELECT * FROM customers WHERE company_id=? ORDER BY id DESC',[company_id()]);View::render('business/customers',compact('rows'));}
 public function saveCustomer():void{$this->guard();verify_csrf();if(trim($_POST['name']??'')===''){flash('error','Le nom du client est obligatoire.');redirect('/customers');}db_exec('INSERT INTO customers(company_id,name,phone,email,address,created_at) VALUES(?,?,?,?,?,NOW())',[company_id(),trim($_POST['name']??''),trim($_POST['phone']??''),trim($_POST['email']??''),trim($_POST['address']??'')]);redirect('/customers');}
 public function sales():void{$this->guard();$rows=db_all('SELECT s.*,c.name customer FROM sales s LEFT JOIN customers c ON c.id=s.customer_id AND c.company_id=s.company_id WHERE s.company_id=? ORDER BY s.id DESC',[company_id()]);View::render('business/sales',compact('rows'));}
 public function saleForm():void{$this->guard();$customers=db_all('SELECT id,name FROM customers WHERE company_id=? ORDER BY name',[company_id()]);$products=db_all('SELECT id,name,sell_price,stock FROM products WHERE company_id=? AND stock>0 ORDER BY name',[company_id()]);View::render('business/sale_form',compact('customers','products'));}
 public function saveSale():void{$this->guard();verify_csrf();$pid=$_POST['product_id']??[];$qty=$_POST['quantity']??[];if(!$pid){flash('error','Ajoutez au moins un produit.');redirect('/sales/create');}$pdo=Database::p();$pdo->beginTransaction();try{$items=[];$total=0;foreach($pid as $i=>$p){$product=db_one('SELECT * FROM products WHERE id=? AND company_id=? FOR UPDATE',[(int)$p,company_id()]);$q=max(1,(int)($qty[$i]??1));if(!$product||$product['stock']<$q)throw new RuntimeException('Stock insuffisant pour '.($product['name']??'produit'));$line=$q*(float)$product['sell_price'];$total+=$line;$items[]=[$product,$q,$line];}$customerId=($_POST['customer_id']??'')!==''?(int)$_POST['customer_id']:null;if($customerId && !db_one('SELECT id FROM customers WHERE id=? AND company_id=?',[$customerId,company_id()]))throw new RuntimeException('Client invalide.');$company=db_one('SELECT tax_rate FROM companies WHERE id=?',[company_id()]);$taxRate=(float)($company['tax_rate']??0);$tax=round($total*$taxRate/100,2);$grand=$total+$tax;$invoiceNo='FB-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$saleId=db_exec('INSERT INTO sales(company_id,customer_id,invoice_no,subtotal,tax_amount,total,status,payment_method,created_at) VALUES(?,?,?,?,?,?,"paid",?,NOW())',[company_id(),$customerId,$invoiceNo,$total,$tax,$grand,$_POST['payment_method']??'cash']);foreach($items as [$p,$q,$line]){db_exec('INSERT INTO sale_items(sale_id,product_id,product_name,quantity,unit_price,line_total) VALUES(?,?,?,?,?,?)',[$saleId,$p['id'],$p['name'],$q,$p['sell_price'],$line]);Database::p()->prepare('UPDATE products SET stock=stock-? WHERE id=? AND company_id=?')->execute([$q,$p['id'],company_id()]);try{db_exec('INSERT INTO stock_movements(company_id,product_id,user_id,type,quantity,reason,created_at) VALUES(?,?,?,"out",?,?,NOW())',[company_id(),$p['id'],Auth::user()['id'],$q,'Vente '.$saleId]);}catch(Throwable $ignored){}} $pdo->commit();redirect('/invoices');}catch(Throwable $e){$pdo->rollBack();flash('error',$e->getMessage());redirect('/sales/create');}}
 public function invoices():void{$this->guard();$rows=db_all('SELECT s.*,c.name customer FROM sales s LEFT JOIN customers c ON c.id=s.customer_id AND c.company_id=s.company_id WHERE s.company_id=? ORDER BY s.id DESC',[company_id()]);View::render('business/invoices',compact('rows'));}
 public function invoice():void{$this->guard();$id=(int)($_GET['id']??0);$sale=db_one('SELECT s.*,c.name customer,c.phone,c.address FROM sales s LEFT JOIN customers c ON c.id=s.customer_id AND c.company_id=s.company_id WHERE s.id=? AND s.company_id=?',[$id,company_id()]);if(!$sale){http_response_code(404);exit('Facture introuvable');}$items=db_all('SELECT * FROM sale_items WHERE sale_id=?',[$id]);$company=db_one('SELECT * FROM companies WHERE id=?',[company_id()]);View::render('business/invoice',compact('sale','items','company'));}
 public function expenses():void{$this->guard();$rows=db_all('SELECT * FROM expenses WHERE company_id=? ORDER BY expense_date DESC',[company_id()]);View::render('business/expenses',compact('rows'));}
 public function saveExpense():void{$this->guard();verify_csrf();db_exec('INSERT INTO expenses(company_id,label,category,amount,expense_date,note) VALUES(?,?,?,?,?,?)',[company_id(),trim($_POST['label']??''),trim($_POST['category']??''),(float)($_POST['amount']??0),$_POST['expense_date']??date('Y-m-d'),trim($_POST['note']??'')]);redirect('/expenses');}
 public function reports():void{$this->guard();$id=company_id();$months=db_all('SELECT DATE_FORMAT(created_at,"%Y-%m") month, SUM(total) total FROM sales WHERE company_id=? AND created_at>=DATE_SUB(CURRENT_DATE(),INTERVAL 6 MONTH) GROUP BY month ORDER BY month',[$id]);$profit=(float)(db_one('SELECT COALESCE(SUM(si.line_total-(p.buy_price*si.quantity)),0) n FROM sale_items si JOIN sales s ON s.id=si.sale_id JOIN products p ON p.id=si.product_id WHERE s.company_id=?',[$id])['n']??0);View::render('business/reports',compact('months','profit'));}
 public function settings():void{$this->guard();$company=db_one('SELECT * FROM companies WHERE id=?',[company_id()]);View::render('business/settings',compact('company'));}
 public function saveSettings():void{$this->guard();verify_csrf();Database::p()->prepare('UPDATE companies SET name=?,sector=?,phone=?,address=?,city=?,ifu=?,tax_rate=? WHERE id=?')->execute([trim($_POST['name']??''),trim($_POST['sector']??''),trim($_POST['phone']??''),trim($_POST['address']??''),trim($_POST['city']??''),trim($_POST['ifu']??''),max(0,min(100,(float)($_POST['tax_rate']??0))),company_id()]);flash('success','Informations mises à jour.');redirect('/settings');}
}
